  content: string;
}

export interface SoftwareProject {
  projectName: string;
  description: string;
  files: GeneratedFile[];
}

export type ArchitectPersona = 'RADIUM' | 'GROK_MODE' | 'COPILOT_CORE' | 'NANO_LITE';
export type OutputLanguage = 'English' | 'Bengali' | 'Hebrew' | 'Arabic';

@Injectable({
  providedIn: 'root'
})
export class GeminiService {
  private ai: GoogleGenAI;

  constructor() {
    this.ai = new GoogleGenAI({ apiKey: process.env['API_KEY'] || '' });
  }

  async generateSoftware(prompt: string, persona: ArchitectPersona, language: OutputLanguage): Promise<SoftwareProject> {
    const fileSchema: Schema = {
      type: Type.OBJECT,
      properties: {
        name: { type: Type.STRING, description: "File name with extension (e.g., app.ts)" },
        language: { type: Type.STRING, description: "Programming language (e.g., typescript, python)" },
        content: { type: Type.STRING, description: "The full code content of the file" }
      },
      required: ["name", "language", "content"]
    };

    const projectSchema: Schema = {
      type: Type.OBJECT,
      properties: {
        projectName: { type: Type.STRING },
        description: { type: Type.STRING },
        files: { 
          type: Type.ARRAY,
          items: fileSchema
        }
      },
      required: ["projectName", "description", "files"]
    };

    // Tailor system instruction based on Persona
    let personaInstruction = "";
    switch(persona) {
      case 'GROK_MODE':
        personaInstruction = "You are in Grok Mode. Be witty, slightly rebellious, but write extremely efficient, high-performance code. Use a hacker aesthetic in comments.";
        break;
      case 'COPILOT_CORE':
        personaInstruction = "You are Copilot Core. Be concise, industrial, and focused purely on business logic and standard patterns.";
        break;
      case 'NANO_LITE':
        personaInstruction = "You are Nano Lite. Generate lightweight, minimal, and mobile-optimized code.";
        break;
      default: // RADIUM
        personaInstruction = "You are RadiumAI, a futuristic elite code generator. You write clean, modern, and working code with a sci-fi edge.";
    }

    const fullSystemInstruction = `${personaInstruction} 
    Ensure all comments and documentation within the code are translated to or primarily use ${language} where appropriate, 
    but keep programming keywords in standard English.`;

    const response = await this.ai.models.generateContent({
      model: 'gemini-2.5-flash',
      contents: `Create a software project based on this request: "${prompt}".
      Target Language for comments/docs: ${language}.
      Generate a realistic, multi-file project structure.
      Return the response in strictly valid JSON format.`,
      config: {
        responseMimeType: 'application/json',
        responseSchema: projectSchema,
        systemInstruction: fullSystemInstruction,
        thinkingConfig: { thinkingBudget: 100 }, 
        maxOutputTokens: 2000
      }
    });

    if (response.text) {
      return JSON.parse(response.text) as SoftwareProject;
    }

    throw new Error("Failed to generate software");
  }
}

